def action_output_ref(uuid_str, output_name):
    return {
        "Value": {
            "Type": "ActionOutput",
            "OutputName": output_name,
            "OutputUUID": uuid_str,
        },
        "WFSerializationType": "WFTextTokenAttachment",
    }

def set_var(name, source=None):
    params = {"WFVariableName": name}
    if source is not None:
        params["WFInput"] = source
    return action("is.workflow.actions.setvariable", params)

def download_url_file(url_token, request_var=None, uuid_=None):
    params = {
        "WFURL": url_token,
        "WFHTTPMethod": "POST",
        "WFHTTPBodyType": "File",
        "Advanced": True,
        "UUID": uuid_ or uid(),
    }
    if request_var is not None:
        params["WFRequestVariable"] = request_var
    return action("is.workflow.actions.downloadurl", params)

def download_url_json(url, json_entries, uuid_=None):
    return action(
        "is.workflow.actions.downloadurl",
        {
            "WFURL": tok_plain(url),
            "WFHTTPMethod": "POST",
            "WFHTTPBodyType": "Form",
            "WFFormValues": _dict_field_value(
                [(k, v, "text") for k, v in json_entries]
            ),
            "Advanced": True,
            "UUID": uuid_ or uid(),
        },
    )

def action_output_ref(uuid_str, output_name):
    return {
        "Value": {
            "Type": "ActionOutput",
            "OutputName": output_name,
            "OutputUUID": uuid_str,
        },
        "WFSerializationType": "WFTextTokenAttachment",
    }

def set_var(name, source=None):
    params = {"WFVariableName": name}
    if source is not None:
        params["WFInput"] = source
    return action("is.workflow.actions.setvariable", params)

def build_file():
    download_uuid = uid()
    actions = [
        download_url_file(
            tok_plain(ENDPOINT),
            request_var=tok_shortcut_input_ref(),
            uuid_=download_uuid,
        ),
        *trailing_notify(download_uuid),
    ]
    return top_level(
        actions,
        share_sheet_types=[
            "WFGenericFileContentItem",
            "WFImageContentItem",
            "WFPDFContentItem",
        ],
    )

def build_url():
    download_uuid = uid()
    actions = [
        download_url_json(
            ENDPOINT,
            [("url", tok_shortcut_input_ref())],
            uuid_=download_uuid,
        ),
        *trailing_notify(download_uuid),
    ]
    return top_level(actions, share_sheet_types=["WFURLContentItem"])

if use_dictation:
    input_action = dictate(uuid_=input_uuid)
    input_output = "Dictated Text"

def dictate(uuid_=None):
    return action(
        "is.workflow.actions.dictatetext",
        {
            "WFDictateTextLanguage": {
                "Value": {"Identifier": "en-US"},
                "WFSerializationType": "WFQuantityFieldValue",
            },
            "WFDictateTextStopListening": "After Pause",
            "UUID": uuid_ or uid(),
        },
    )

def build_prose(use_dictation=False):
    input_uuid = uid()
    if use_dictation:
        input_action = dictate(uuid_=input_uuid)
        input_output = "Dictated Text"
    else:
        input_action = ask(
            "Blurb?", multiline=True, default="", uuid_=input_uuid
        )
        input_output = "Provided Input"
    download_uuid = uid()
    actions = [
        input_action,
        set_var("Blurb", source=action_output_ref(input_uuid, input_output)),
        *tag_picker_block(),
        download_url_json(
            ENDPOINT,
            [("blurb", tok_var_ref("Blurb")), ("tags", tok_var_ref("TagsCSV"))],
            uuid_=download_uuid,
        ),
        *trailing_notify(download_uuid),
    ]
    return top_level(actions)
